Integration Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(integration_service, "Integration Service") {
    Component(FHIR Adapter, "FHIR Adapter", "NestJS, TypeScript", "Interfaces with external lab and imaging systems using HL7 FHIR with mTLS and OAuth2.")
    Component(Outbox Message Relay, "Outbox Message Relay", "BullMQ, Redis", "Executes the reliable outbox pattern and dispatches events asynchronously.")
    Component(Audit Logger, "Audit Logger", "Winston, OpenTelemetry", "Handles secure audit logging for compliance and monitoring.")
    Component(DLQ Alert Dispatcher, "DLQ Alert Dispatcher", "NestJS Event Emitter", "Dispatches alerts for dead-letter queue messages.")
}

Rel(Outbox Message Relay, FHIR Adapter, "Internal Function Call / Event Dispatch")
Rel(Outbox Message Relay, DLQ Alert Dispatcher, "Internal Event [Pub/Sub]")
Rel(DLQ Alert Dispatcher, Internal Notification Service, "REST/gRPC [Internal API]")

@enduml

Decoupled Data Tier.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(decoupled_data_tier, "Decoupled Data Tier") {
    Component(Primary Operational Database, "Primary Operational Database", "AWS RDS PostgreSQL & On-premise PostgreSQL", "Primary transactional storage for sub-second EMR performance.")
    Component(Reporting & Analytics Read Replica, "Reporting & Analytics Read Replica", "PostgreSQL Read Replica", "Offloads read-only queries for reporting and analytics.")
    Component(Audit & Archive Manager, "Audit & Archive Manager", "Apache Kafka & Debezium", "Streams change logs via CDC for audit streaming without operational locking.")
    Component(WORM Storage Vault, "WORM Storage Vault", "AWS S3 Object Lock / MinIO", "Immutable WORM storage satisfying greater than or equal to 10-year retention.")
}

Rel(Primary Operational Database, Audit & Archive Manager, "Streams change logs via Debezium CDC (TCP/IP)", "TCP/IP")
Rel(Audit & Archive Manager, WORM Storage Vault, "Writes immutable object archives via HTTPS", "HTTPS")

@enduml
